1	package darksafe
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/binary"
7		"errors"
8		"fmt"
9		"reflect"
10		"testing"
11	)
12	
13	// TestArchiveRoundTripPreservesEveryField archives a live export mixing
14	// resource-restricted publishes, a rollback and decisions, and requires the
15	// decoded material to be deeply identical to the export: order, sequences,
16	// categories, policy versions, rollback source, full requests, decision
17	// explanations, predecessor and own fingerprints, and resource limits.
18	func TestArchiveRoundTripPreservesEveryField(t *testing.T) {
19		s := NewStore()
20		s.Publish("acme", 0, []Policy{
21			{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
22			{ID: "p2", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectDeny, ResourceID: "ledger-甲"},
23		})
24		allowed := s.Decide("acme", request("acme", "u1", "ledger-甲", "org/a", "read"))
25		if allowed.Allowed {
26			t.Fatalf("resource-restricted deny must win: %+v", allowed)
27		}
28		s.Publish("acme", 1, nil)
29		if v, err := s.Rollback("acme", 2, 1); err != nil || v != 3 {
30			t.Fatalf("rollback = %d, %v", v, err)
31		}
32		s.Decide("acme", request("acme", "u1", "other", "org/a", "read"))
33	
34		recs, cp, err := s.AuditExport("acme", 0)
35		if err != nil {
36			t.Fatal(err)
37		}
38		archive, err := EncodeAuditArchive("acme", recs, cp)
39		if err != nil {
40			t.Fatalf("encode: %v", err)
41		}
42		if len(archive) == 0 || !bytes.HasPrefix(archive, []byte(archiveMagic)) {
43			t.Fatal("archive must carry the recognizable framing")
44		}
45		if again, err := EncodeAuditArchive("acme", recs, cp); err != nil || !bytes.Equal(again, archive) {
46			t.Fatalf("encoding must be deterministic: equal=%v err=%v", bytes.Equal(again, archive), err)
47		}
48	
49		got, err := DecodeAuditArchive(archive, "acme", cp)
50		if err != nil {
51			t.Fatalf("decode: %v", err)
52		}
53		if !reflect.DeepEqual(got, recs) {
54			t.Fatalf("decoded records differ from export:\n got %+v\nwant %+v", got, recs)
55		}
56	
57		// The decoded records feed the existing offline review entry directly.
58		for _, seq := range []int{2, 5} {
59			review, err := RecheckDecisionOffline("acme", got, cp, seq)
60			if err != nil {
61				t.Fatalf("offline review seq %d after archive: %v", seq, err)
62			}
63			if !review.Consistent {
64				t.Fatalf("seq %d review inconsistent: %+v", seq, review)
65			}
66		}
67	}
68	
69	// TestArchiveEmptyOrgUsesGenesisCheckpoint archives and reads an
70	// organization with no records, pinned by its sequence-0 root checkpoint.
71	func TestArchiveEmptyOrgUsesGenesisCheckpoint(t *testing.T) {
72		s := NewStore()
73		recs, cp, err := s.AuditExport("ghost", 0)
74		if err != nil {
75			t.Fatal(err)
76		}
