163		}
164		shapes = append(shapes, syntheticRecord(org, 2, AuditPolicyChange, &PolicyChange{
165			Version: 2, Policies: []Policy{}, // non-nil empty policy set
166			SourceVersion: 1, RolledBack: true,
167		}, nil, shapes[0].Fingerprint))
168		shapes = append(shapes, syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
169			Request: OrgRequest{
170				SubjectOrg:  org,
171				ResourceOrg: org,
172				Subject: Subject{
173					ID: " 中\t\n\r \"\\\x00\x01 " + invalidByte,
174					// nil roles
175				},
176				Resource: Resource{ID: "r", Scope: "org/a"},
177				Action:   "read ",
178			},
179			Decision: Decision{Allowed: true, Reason: "理" + invalidByte + "由", Matched: nil},
180		}, shapes[1].Fingerprint))
181		shapes = append(shapes, syntheticRecord(org, 4, AuditDecision, nil, &DecisionRecord{
182			Request: OrgRequest{
183				SubjectOrg: org, ResourceOrg: org,
184				Subject:  Subject{ID: "u", Roles: []string{}}, // empty non-nil roles
185				Resource: Resource{ID: "r", Scope: "org/a"},
186				Action:   "read",
187			},
188			Decision: Decision{Allowed: false, Reason: "x", Matched: []string{}}, // empty non-nil matched
189		}, shapes[2].Fingerprint))
190		shapeCP := Checkpoint{Org: org, EndSeq: 4, Fingerprint: shapes[3].Fingerprint}
191		arch, err := EncodeAuditArchive(org, shapes, shapeCP)
192		if err != nil {
193			t.Fatalf("encode shapes: %v", err)
194		}
195		back, err := DecodeAuditArchive(arch, org, shapeCP)
196		if err != nil {
197			t.Fatalf("decode shapes: %v", err)
198		}
199		if !reflect.DeepEqual(back, shapes) {
200			t.Fatalf("nil/empty/absent shapes changed:\n got %+v\nwant %+v", back, shapes)
201		}
202		if back[0].Change.Policies != nil {
203			t.Fatal("nil policy set decoded as non-nil")
204		}
205		if back[1].Change.Policies == nil || len(back[1].Change.Policies) != 0 {
206			t.Fatal("empty policy set must decode non-nil and empty")
207		}
208		if back[2].Decision.Request.Subject.Roles != nil {
209			t.Fatal("nil roles decoded as non-nil")
210		}
211		if back[3].Decision.Request.Subject.Roles == nil {
212			t.Fatal("empty roles decoded as nil")
213		}
214		if back[3].Decision.Decision.Matched == nil {
215			t.Fatal("empty matched list decoded as nil")
216		}
